/* Logo de acceso ThinkStore: mismo archivo transparente de la nota de entrega. */
(function(){'use strict';
const logo="data:image/png;base64,";
const selector='.ts-login-top a>img,.top>.brand>img,.auth-brand img,.logo-wrap img,.welcome-logo,.login-brand>img,#lockScreen .lock-logo,.support-login-brand>img,.gate-logo>img,.card>img.logo,body[data-ts-surface="store"] .ts-clean-brand>img,body[data-ts-surface="store"] .ts-footer-brand>a>img';
const style=document.createElement('style');style.textContent=`
[data-ts-login-logo]{width:88px!important;height:96px!important;max-width:100%!important;object-fit:contain!important;object-position:center!important;background:transparent!important;border:0!important;border-radius:0!important;box-shadow:none!important;display:block!important;flex-shrink:0!important}
.ts-login-top [data-ts-login-logo],.top>.brand>[data-ts-login-logo]{width:40px!important;height:46px!important}.auth-brand,.logo-wrap{margin-bottom:24px!important}.login-brand>[data-ts-login-logo],.support-login-brand>[data-ts-login-logo]{width:66px!important;height:74px!important}#lockScreen [data-ts-login-logo]{width:100px!important;height:108px!important;margin-bottom:18px!important}.gate-logo>[data-ts-login-logo]{width:90px!important;height:98px!important}
.gate-logo{width:100px!important;height:108px!important;min-height:108px!important;padding:0!important;background:transparent!important;border:0!important;border-radius:0!important;box-shadow:none!important;overflow:visible!important;display:flex!important;align-items:center!important;justify-content:center!important}.gate-logo>[data-ts-login-logo]{width:100px!important;height:108px!important;filter:none!important}
body[data-ts-surface="store"] .top.ts-clean-header .ts-clean-brand>[data-ts-login-logo]{width:62px!important;height:68px!important;object-fit:contain!important;border-radius:0!important}body[data-ts-surface="store"] .ts-footer-brand>a>[data-ts-login-logo]{width:92px!important;height:104px!important;filter:invert(1)!important}
@media(max-width:700px){body[data-ts-surface="store"] .top.ts-clean-header .ts-clean-brand>[data-ts-login-logo]{width:48px!important;height:54px!important}}
@media(max-width:640px){[data-ts-login-logo]{width:76px!important;height:84px!important}.auth-brand,.logo-wrap{margin-bottom:20px!important}.support-login-brand>[data-ts-login-logo],.login-brand>[data-ts-login-logo]{width:60px!important;height:68px!important}}
`;document.head.appendChild(style);
function apply(root){const imgs=[...(root.matches?.(selector)?[root]:[]),...(root.querySelectorAll?.(selector)||[])];for(const img of imgs){if(img.dataset.tsLoginLogo)continue;img.dataset.tsLoginLogo='1';img.removeAttribute('onerror');img.src=logo;img.alt='ThinkStore';const card=img.closest('.lock-card,.support-login-card,.online-gate-card');const color=card&&getComputedStyle(card).color.match(/[\d.]+/g);img.style.setProperty('filter',img.closest('.ts-footer-brand')||color&&Number(color[0])+Number(color[1])+Number(color[2])>510?'invert(1)':'none','important');}}
apply(document);new MutationObserver(changes=>{for(const change of changes)for(const node of change.addedNodes)if(node.nodeType===1)apply(node)}).observe(document.body,{childList:true,subtree:true});
})();
